head.b:skin:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg: #F5F3EE;
  --ink: #1A1917;
  --ink2: #6B6860;
  --ink3: #A8A59E;
  --box: #E8E5DE;
  --border: #C8C4BB;
  --white: #FFFFFF;
  --yellow: #F5E642;
  --r: 4px;
  --font: 'DM Sans', system-ui, sans-serif;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  font-size: 17px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
a { color: inherit; }
img { max-width: 100%; height: auto; }

.container { max-width: 960px; margin: 0 auto; padding: 0 32px; }
.narrow { max-width: 760px; margin: 0 auto; padding: 0 32px; }

/* ESCONDE LIXO PADRAO DO BLOGGER */
#header, .header-outer, .Header { display: none !important; }
.date-header, h2.date-header { display: none !important; }
.post-footer, .post-footer-line, .post-header { display: none !important; }
.comments, #comments, .post-comment-link { display: none !important; }
.feed-links, .post-feeds { display: none !important; }
.widget-item-control, .quickedit, .home-link { display: none !important; }
.navbar, #navbar, #Navbar1 { display: none !important; height: 0 !important; visibility: hidden !important; }
.post-share-buttons, .post-labels { display: none !important; }
.byline.reactions { display: none !important; }

/* NAV PRETA */
#nav-bar {
  background: #000;
  border-bottom: 1px solid #2a2a2a;
  position: sticky;
  top: 0;
  z-index: 100;
}
#nav-bar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 56px;
}
.nav-logo {
  font-size: 15px;
  font-weight: 700;
  color: #fff;
  text-decoration: none;
  letter-spacing: .02em;
}
.nav-right { display: flex; align-items: center; gap: 20px; }
.nav-link {
  font-size: 13px;
  color: #A0A0A0;
  text-decoration: none;
  font-weight: 500;
}
.nav-link:hover { color: #fff; }
.nav-cta {
  font-size: 13px;
  font-weight: 700;
  background: #fff;
  color: #000;
  padding: 8px 16px;
  border-radius: var(--r);
  text-decoration: none;
  letter-spacing: .03em;
  white-space: nowrap;
}
.nav-cta:hover { opacity: .85; }

/* HERO ESCURO */
.hero {
  background: #1A1917;
  color: #fff;
  padding: 88px 0 80px;
  border-bottom: 1px solid #2a2a2a;
}
.hero-tag {
  display: inline-block;
  font-size: 10px;
  letter-spacing: .12em;
  text-transform: uppercase;
  border: 1px solid #3a3a38;
  padding: 5px 11px;
  border-radius: 2px;
  color: #A8A59E;
  margin-bottom: 22px;
}
.hero h1 {
  font-size: clamp(32px, 5vw, 46px);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -.02em;
  margin-bottom: 20px;
  max-width: 720px;
}
.hero h1 .hl {
  background: #fff;
  color: #000;
  padding: 0 7px;
}
.hero-sub {
  font-size: 17px;
  color: #C8C4BB;
  line-height: 1.7;
  max-width: 560px;
  margin-bottom: 30px;
}
.hero-cta { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; }
.btn-primary {
  display: inline-flex;
  align-items: center;
  font-size: 14px;
  font-weight: 700;
  background: var(--yellow);
  color: #000;
  padding: 15px 26px;
  border-radius: var(--r);
  text-decoration: none;
  letter-spacing: .02em;
  transition: transform .15s;
}
.btn-primary:hover { transform: translateY(-2px); }
.hero-trust {
  display: flex;
  gap: 22px;
  flex-wrap: wrap;
  margin-top: 30px;
}
.trust-item {
  font-size: 10px;
  letter-spacing: .05em;
  text-transform: uppercase;
  color: #A8A59E;
  display: flex;
  align-items: center;
  gap: 6px;
}
.trust-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--yellow); }

/* BARRA DE TITULO (paginas de post) */
.page-band {
  background: #1A1917;
  color: #fff;
  padding: 36px 0;
  border-bottom: 1px solid #2a2a2a;
}
.page-band a {
  font-size: 12px;
  color: #A8A59E;
  text-decoration: none;
  letter-spacing: .04em;
}
.page-band a:hover { color: #fff; }

/* SECTION LABEL NUMERADO */
.sec-label {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 10px;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--ink3);
  margin-bottom: 28px;
}
.sec-num {
  font-size: 10px;
  background: var(--ink);
  color: var(--bg);
  padding: 2px 7px;
  border-radius: 2px;
}
.sec-label::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border);
}

/* AREA DOS POSTS */
.main-outer { padding: 64px 0 24px; }

.post-outer, .post-outer-container {
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--r);
  padding: 32px;
  margin-bottom: 20px;
}

.post-title, h3.post-title, h1.post-title {
  font-size: 23px;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: 16px;
  letter-spacing: -.01em;
}
.post-title a { color: var(--ink); text-decoration: none; }
.post-title a:hover { color: var(--ink2); }

.post-body, .post-body.entry-content {
  font-size: 16px;
  line-height: 1.75;
  color: var(--ink);
}
.post-body p { margin-bottom: 14px; }
.post-body h2 { font-size: 20px; font-weight: 700; margin: 28px 0 10px; }
.post-body h3 { font-size: 17px; font-weight: 700; margin: 22px 0 8px; }
.post-body ul, .post-body ol { margin: 0 0 14px 22px; }
.post-body li { margin-bottom: 4px; }
.post-body strong { font-weight: 700; }
.post-body a { color: var(--ink); font-weight: 600; text-decoration: underline; }
.post-body img { border-radius: var(--r); border: 1px solid var(--border); margin: 18px 0; }

/* INDEX: grid de 3 cards pequenos */
body.index .blog-posts {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
body.index .date-outer,
body.index .date-posts { display: contents; }
body.index .post-outer,
body.index .post-outer-container {
  margin: 0;
  padding: 22px;
  display: flex;
  flex-direction: column;
  transition: transform .15s, box-shadow .15s;
}
body.index .post-outer:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(0,0,0,.08);
}
body.index .post-title,
body.index h3.post-title {
  font-size: 15px;
  line-height: 1.4;
  margin-bottom: 0;
}
body.index .post-body,
body.index .post-jump-link,
body.index .jump-link { display: none; }
body.index .post-outer::after {
  content: 'Ler artigo \2192';
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .04em;
  text-transform: uppercase;
  color: var(--ink3);
  margin-top: auto;
  padding-top: 16px;
}

/* ITEM: artigo unico centralizado */
body.item .post-outer,
body.item .post-outer-container {
  max-width: 760px;
  margin: 0 auto 20px;
}

@media (max-width: 760px) {
  body.index .blog-posts { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 480px) {
  body.index .blog-posts { grid-template-columns: 1fr; }
}

/* PAGINACAO */
.blog-pager, #blog-pager {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  padding: 16px 0 0;
}
.blog-pager a, #blog-pager a {
  font-size: 13px;
  font-weight: 600;
  color: var(--ink2);
  text-decoration: none;
  border: 1px solid var(--border);
  padding: 9px 18px;
  border-radius: var(--r);
  background: var(--white);
}
.blog-pager a:hover, #blog-pager a:hover { border-color: var(--ink); color: var(--ink); }

/* BANNER CTA */
.cta-band { padding: 40px 0 72px; }
.cta-box {
  background: var(--ink);
  color: var(--bg);
  border-radius: var(--r);
  padding: 48px 32px;
  text-align: center;
}
.cta-box .kicker {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--ink3);
  display: block;
  margin-bottom: 14px;
}
.cta-box h2 { font-size: 25px; font-weight: 700; line-height: 1.25; margin-bottom: 10px; }
.cta-box p { font-size: 14px; color: #C8C4BB; margin-bottom: 4px; }
.cta-box .price { font-size: 40px; font-weight: 700; margin: 16px 0 20px; }
.cta-box .btn {
  display: inline-block;
  font-size: 14px;
  font-weight: 700;
  background: var(--yellow);
  color: var(--ink);
  padding: 15px 30px;
  border-radius: var(--r);
  text-decoration: none;
}
.cta-box .btn:hover { opacity: .9; }
.cta-box .note { display: block; font-size: 12px; color: var(--ink3); margin-top: 14px; }

/* RODAPE */
#site-footer {
  background: #000;
  color: #fff;
  padding: 40px 0;
}
.footer-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px;
}
.footer-logo { font-size: 14px; font-weight: 700; color: #fff; text-decoration: none; }
.footer-link {
  font-size: 11px;
  color: #A0A0A0;
  text-decoration: none;
  letter-spacing: .05em;
  text-transform: uppercase;
}
.footer-link:hover { color: #fff; }
.footer-disc {
  font-size: 10px;
  color: #888;
  text-align: center;
  line-height: 1.7;
  margin-top: 20px;
}

@media (max-width: 600px) {
  .container, .narrow { padding: 0 22px; }
  .post-outer, .post-outer-container { padding: 22px; }
  .hero { padding: 60px 0 56px; }
}
